/** Production origin. Canonical URLs, the sitemap and structured data are all built from it. */
export const SITE_URL = 'https://upvote.app';
export const SITE_NAME = 'Upvote';
export const LEGAL_NAME = 'Upvote Technologies Inc.';
export const CONTACT_EMAIL = 'admin@upvote.app';
/** 1200x630 social card, generated by `scripts/brand-assets.mjs`. */
export const DEFAULT_OG_IMAGE = '/og.png';
/** The same card with its text in each language; a page without its own image gets this one. */
export const OG_IMAGE_BY_LOCALE = { en: DEFAULT_OG_IMAGE, 'pt-br': '/og-pt-br.png' } as const;

export function absoluteUrl(path: string): string {
  return new URL(path, SITE_URL).toString();
}
